// Kaya v2 — every sentence Kaya can send, in one place (wording agreed with Marc).
// The flow (flow.ts) decides WHICH of these to send; nothing here is generated by AI.

export type QuestionKey =
  | "price" | "home_visit" | "free" | "commission" | "hours" | "location" | "how_it_works"
  | "payment" | "documents" | "loan" | "expired_registration" | "not_running" | "company_car"
  | "lost_mulkiya" | "other_emirate" | "duration" | "accident" | "are_you_bot" | "other";

export const LOCATION =
  "📍 Mister Wheelz Car Buyers\n\nUmm Suqeim Branch, Al Quoz 4, Dubai\n\nhttps://maps.app.goo.gl/nv6Yy7uKqVCnkcVx6\n\nCall Center\n+971 58 582 5543";

export const BOOKING_NOTE = "*We will confirm the details and timing with you in the morning*";

export function salutation(now: Date): string {
  const h = new Date(+now + 4 * 3600e3).getUTCHours();
  return h < 12 ? "Good morning" : h < 17 ? "Good afternoon" : "Good evening";
}

export const greeting = (now: Date) =>
  `${salutation(now)}! I'm Kaya from Mister Wheelz 😊 Before we start may I know your name please?`;
export const greetingWithName = (now: Date, name: string) =>
  `${salutation(now)}! I'm Kaya from Mister Wheelz 😊 Nice to meet you, ${name}.`;

