export const FILLERS = ["Great.", "Alright.", "Thanks.", "Perfect."];

export function inspectionDay(date: string): string {
  const d = new Date(date + "T12:00:00Z"), n = d.getUTCDate();
  const suffix = n % 100 >= 11 && n % 100 <= 13 ? "th" : ({ 1: "st", 2: "nd", 3: "rd" } as Record<number, string>)[n % 10] || "th";
  return d.toLocaleDateString("en-GB", { weekday: "long", timeZone: "UTC" }) + " " + n + suffix + " of " +
    d.toLocaleDateString("en-GB", { month: "long", timeZone: "UTC" });
}
export function inspectionTime(time: string): string {
  const [h, m] = time.split(":").map(Number);
  return (h % 12 || 12) + (m ? ":" + String(m).padStart(2, "0") : "") + " " + (h >= 12 ? "pm" : "am");
}
export const dayLabel = (date: string, today: string, tomorrow: string) =>
  date === today ? "today" : date === tomorrow ? "tomorrow (" + inspectionDay(date) + ")" : inspectionDay(date);

export const offerTwo = (label: string, a: string, b: string) =>
  `Would ${inspectionTime(a)} or ${inspectionTime(b)} ${label} suit you?`;
export const confirmTentative = (date: string, time: string) =>
  `Shall I book you on ${inspectionDay(date)} at ${inspectionTime(time)}?`;
export const booked = (date: string, time: string) =>
  `Your free inspection is confirmed for\n\n${inspectionDay(date)} at ${inspectionTime(time)}.\n\n${LOCATION}\n\n${BOOKING_NOTE}`;
export const AFTER_BOOKING_NAME = "May I have your name for the booking?";
export const AFTER_BOOKING_NAME_PHONE = "May I have your name and a UAE contact number for the booking?";
export const AFTER_BOOKING_PHONE = "May I have a UAE contact number for the booking?";

export function sundayClosed(now: Date): string {
  const dow = new Date(+now + 4 * 3600e3).getUTCDay();
  if (dow === 5) return "We're closed on Sundays, but we're open tomorrow (Saturday) from 10 am.";
  if (dow === 6) return "We're closed on Sundays. We're open again on Monday from 10 am.";
  return "We're closed on Sundays. We're open on Friday from 12 pm and Saturday from 10 am.";
}
export const closedThen = (label: string, opens: string) => `That time is outside our opening hours. On ${label} we're open from ${opens} until 7 pm.`;
export const closedNow = (label: string, opens: string) => `We're closed right now, but we open again ${label} at ${opens}.`;

