// ── Answers to questions and objections (section 4 of the board) ────────
export function answer(q: QuestionKey, ctx: { year?: number | null }): string {
  switch (q) {
    case "price": {
      const base = "We give the final price after the inspection, once we have the complete details of the car. Any price is discussed with our team after the inspection.";
      return ctx.year && ctx.year >= 2020
        ? base + "\n\nFor your car we offer two options: cash on the spot, or consignment, where we sell it for you through our showroom directly to an end user. Both options can be discussed with our team after the inspection."
        : base;
    }
    case "home_visit": return "All our inspections are done at our branch in Al Quoz, and it only takes 10–15 minutes.";
    case "free": return "Yes, the inspection is completely free.";
    case "commission": return "There's no commission. We buy the car from you directly.";
    case "hours": return "We're open Monday to Saturday from 10 am to 7 pm (Friday from 12 pm), and closed on Sundays.";
    case "location": return LOCATION;
    case "how_it_works": return "It's very simple: we buy the car cash on the spot. Before we do, we check your car very quickly just to see if everything's ok and we both agree we'll buy it off you at the same time.";
    case "payment": return "We pay cash on the spot when the car is transferred. A bank transfer can be arranged on request.";
    case "documents": return "Please bring your Emirates ID and the Mulkiya (the car's registration card). The digital Mulkiya in the RTA app is fine too.";
    case "loan": return "No problem. We settle the outstanding loan with your bank for you, at no extra cost. It usually takes 1–3 working days, and once RTA releases the mortgage the car can be transferred straight away.";
    case "expired_registration": return "Expired registration or insurance is no problem. If you'd rather not drive it, you can bring it on a recovery truck.";
    case "not_running": return "Please bring the car in running condition, so we can do a fair inspection.";
    case "company_car": return "Company-registered cars are fine. They need a few extra documents, and our team will help you with them.";
    case "lost_mulkiya": return "No problem, you can use the digital Mulkiya in the RTA app.";
    case "other_emirate": return "Yes, we buy cars registered in any emirate.";
    case "duration": return "The inspection only takes 10–15 minutes.";
    case "accident": return "No problem, we buy cars with accident history too. It's taken into account in the final price.";
    case "are_you_bot": return "I'm Kaya, the virtual assistant of Mister Wheelz.";
    case "other": return "I'll note that for our team.";
  }
}
